CREATE TABLE IF NOT EXISTS duranki_service_write_lock(service VARCHAR(30) PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS duranki_service_migration(service VARCHAR(30) PRIMARY KEY,source_sha256 CHAR(64) NOT NULL,counts_json LONGTEXT NOT NULL,migrated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT IGNORE INTO duranki_service_write_lock VALUES('cycle');
CREATE TABLE IF NOT EXISTS cycle_request(id VARCHAR(200) PRIMARY KEY,user_id VARCHAR(200) NOT NULL,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,description TEXT NOT NULL,amount_cents BIGINT NOT NULL CHECK(amount_cents>0),currency VARCHAR(10) NOT NULL DEFAULT 'ZAR',mode VARCHAR(20) NOT NULL,status VARCHAR(80) NOT NULL DEFAULT 'PENDING',review_required TINYINT NOT NULL DEFAULT 0,provider_id VARCHAR(200) UNIQUE,reference VARCHAR(200) NOT NULL UNIQUE,created_by VARCHAR(200) NOT NULL,created_at VARCHAR(40) NOT NULL,charged_at VARCHAR(40)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_event(hash CHAR(64) PRIMARY KEY,request_id VARCHAR(200) NOT NULL,status VARCHAR(80) NOT NULL,received_at VARCHAR(40) NOT NULL,FOREIGN KEY(request_id) REFERENCES cycle_request(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(200) NOT NULL,actor VARCHAR(200) NOT NULL,action VARCHAR(100) NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(request_id) REFERENCES cycle_request(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_subscription(id VARCHAR(200) PRIMARY KEY,user_id VARCHAR(200) NOT NULL,tenant_id VARCHAR(200) NOT NULL,community_id VARCHAR(200) NOT NULL,service_code VARCHAR(100) NOT NULL,amount_cents BIGINT NOT NULL,price_revision INT NOT NULL,price_snapshot LONGTEXT NOT NULL,mode VARCHAR(20) NOT NULL,state VARCHAR(30) NOT NULL DEFAULT 'PENDING',consent_version VARCHAR(100) NOT NULL,consented_at VARCHAR(40) NOT NULL,token TEXT,paid_until VARCHAR(40),cancelled_at VARCHAR(40),created_at VARCHAR(40) NOT NULL,open_marker TINYINT GENERATED ALWAYS AS (CASE WHEN cancelled_at IS NULL THEN 1 ELSE NULL END) STORED,UNIQUE(user_id,community_id,service_code,mode,open_marker)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_intent(request_id VARCHAR(200) PRIMARY KEY,purpose VARCHAR(30) NOT NULL,subscription_id VARCHAR(200),period_start VARCHAR(40),client_key VARCHAR(100) NOT NULL,user_id VARCHAR(200) NOT NULL,UNIQUE(user_id,client_key),UNIQUE(subscription_id,period_start),FOREIGN KEY(request_id) REFERENCES cycle_request(id),FOREIGN KEY(subscription_id) REFERENCES cycle_subscription(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_fulfilment(request_id VARCHAR(200) PRIMARY KEY,applied_at VARCHAR(40) NOT NULL,FOREIGN KEY(request_id) REFERENCES cycle_request(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_dispatch(request_id VARCHAR(200) PRIMARY KEY,state VARCHAR(30) NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(request_id) REFERENCES cycle_request(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS cycle_consent(request_id VARCHAR(200) PRIMARY KEY,user_id VARCHAR(200) NOT NULL,version VARCHAR(100) NOT NULL,amount_cents BIGINT NOT NULL,accepted_at VARCHAR(40) NOT NULL,FOREIGN KEY(request_id) REFERENCES cycle_request(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
